(async () => {
  const checks=[];
  const assert=(ok,message='assertion failed')=>{if(!ok)throw Error(message);};
  const equal=(a,b)=>assert(JSON.stringify(a)===JSON.stringify(b),JSON.stringify({actual:a,expected:b}));
  const raises=(f,C,name)=>{let e;try{f();}catch(error){e=error;}assert(e instanceof C&&(!name||e.name===name),'expected '+(name||C.name)+', got '+e);};
  const rejects=async(f,C,name)=>{let p;try{p=f();}catch(e){throw Error('synchronous throw: '+e);}assert(p&&typeof p.then==='function');let e;try{await p;}catch(error){e=error;}assert(e instanceof C&&(!name||e.name===name),'expected rejection '+(name||C.name)+', got '+e);};
  for(const [index,w] of [window,document.querySelector('iframe').contentWindow].entries()) {
    const P=w.RTCPeerConnection,S=w.RTCRtpSender;
    const check=async(name,action)=>{const key=index+':'+name;globalThis.__codecCurrentCheck=key;try{await action();checks.push({name:key,passed:true});}catch(error){checks.push({name:key,passed:false,error:{name:error.name,message:error.message}});}};
    const withPC=async(action)=>{const pc=new P();try{await action(pc);}finally{pc.close();}};
    const sender=(pc,kind='audio',init)=>pc.addTransceiver(kind,init).sender;
    for(const [name,length] of [['getParameters',0],['setParameters',1],['replaceTrack',1],['setStreams',0]])await check(name+' descriptor',()=>{const d=Object.getOwnPropertyDescriptor(S.prototype,name);assert(d.enumerable&&d.configurable&&d.writable&&typeof d.value==='function'&&d.value.name===name&&d.value.length===length);});
    for(const kind of ['audio','video']) {
      await check(kind+' initial native parameters',()=>withPC(pc=>{const s=sender(pc,kind),p=s.getParameters();assert(p instanceof w.Object&&p.encodings instanceof w.Array&&p.rtcp instanceof w.Object);assert(typeof p.transactionId==='string'&&p.transactionId.length>0);equal(p.codecs,[]);equal(p.headerExtensions,[]);assert(p.encodings.length===1&&p.encodings[0].active===true&&p.rtcp.reducedSize===false);if(kind==='audio')assert(!('scaleResolutionDownBy' in p.encodings[0]));}));
      await check(kind+' independent returned objects stable same-task transaction',()=>withPC(pc=>{const s=sender(pc,kind),a=s.getParameters(),b=s.getParameters();assert(a!==b&&a.encodings!==b.encodings&&a.encodings[0]!==b.encodings[0]&&a.rtcp!==b.rtcp&&a.transactionId===b.transactionId);a.encodings[0].active=false;a.rtcp.cname='forged';const c=s.getParameters();assert(c.encodings[0].active===true&&c.rtcp.cname!=='forged');}));
      await check(kind+' transaction survives promise microtasks',()=>withPC(async pc=>{const s=sender(pc,kind),a=s.getParameters().transactionId;await Promise.resolve();await Promise.resolve();assert(s.getParameters().transactionId===a);}));
      await check(kind+' transaction expires across createOffer networking task',()=>withPC(async pc=>{const s=sender(pc,kind),old=s.getParameters();await pc.createOffer();assert(old.transactionId!==s.getParameters().transactionId);await rejects(()=>s.setParameters(old),w.DOMException,'InvalidModificationError');}));
      await check(kind+' setParameters unchanged',()=>withPC(async pc=>{const s=sender(pc,kind),p=s.getParameters();assert(await s.setParameters(p)===undefined);assert(p.transactionId!==s.getParameters().transactionId);}));
      await check(kind+' setParameters local encoding update',()=>withPC(async pc=>{const s=sender(pc,kind),p=s.getParameters();p.encodings[0].active=false;p.encodings[0].maxBitrate=64000;let settled=false;const promise=s.setParameters(p);promise.then(()=>settled=true);assert(!settled&&s.getParameters().encodings[0].active);await promise;const next=s.getParameters();assert(settled&&!next.encodings[0].active&&next.encodings[0].maxBitrate===64000);}));
      await check(kind+' converted snapshot ignores later input mutation',()=>withPC(async pc=>{const s=sender(pc,kind),p=s.getParameters();p.encodings[0].active=false;const done=s.setParameters(p);p.encodings[0].active=true;p.encodings[0].maxBitrate=1;await done;assert(s.getParameters().encodings[0].active===false&&!('maxBitrate' in s.getParameters().encodings[0]));}));
      await check(kind+' optional maxBitrate can be removed',()=>withPC(async pc=>{const s=sender(pc,kind);let p=s.getParameters();p.encodings[0].maxBitrate=100;await s.setParameters(p);p=s.getParameters();delete p.encodings[0].maxBitrate;await s.setParameters(p);assert(!('maxBitrate' in s.getParameters().encodings[0]));}));
      for(const [name,modify] of [['transaction',p=>p.transactionId='forged'],['codecs',p=>p.codecs=[{mimeType:'audio/opus',clockRate:48000,payloadType:111,channels:2}]],['header extensions',p=>p.headerExtensions=[{id:1,uri:'urn:forged'}]],['RTCP CNAME',p=>p.rtcp.cname='forged'],['RTCP reducedSize',p=>p.rtcp.reducedSize=true],['add encoding',p=>p.encodings.push({active:true})],['remove encoding',p=>p.encodings=[]],['add RID',p=>p.encodings[0].rid='a']])await check(kind+' immutable '+name,()=>withPC(async pc=>{const s=sender(pc,kind),p=s.getParameters();modify(p);await rejects(()=>s.setParameters(p),w.DOMException,'InvalidModificationError');}));
      await check(kind+' parameters require a fresh transaction',()=>withPC(async pc=>{const s=sender(pc,kind);await rejects(()=>s.setParameters({transactionId:'missing',codecs:[],headerExtensions:[],rtcp:{},encodings:[{}]}),w.DOMException,'InvalidStateError');}));
      await check(kind+' stopped sender rejects after conversion',()=>withPC(async pc=>{const t=pc.addTransceiver(kind),s=t.sender,p=s.getParameters();t.stop();await rejects(()=>s.setParameters(p),w.DOMException,'InvalidStateError');const sentinel={};try{await s.setParameters({get codecs(){throw sentinel;}});assert(false);}catch(e){assert(e===sentinel);}assert(s.getParameters().encodings.length===1);}));
      for(const field of ['maxFramerate','scaleResolutionDownBy'])for(const value of [Infinity,-Infinity,NaN])await check(kind+' finite '+field+' '+String(value),()=>withPC(async pc=>{const s=sender(pc,kind),p=s.getParameters();p.encodings[0][field]=value;await rejects(()=>s.setParameters(p),w.TypeError);}));
      await check(kind+' getter exceptions preserve identity in rejected promises',()=>withPC(async pc=>{const s=sender(pc,kind),sentinel={};const p=s.setParameters({get codecs(){throw sentinel;}});assert(p instanceof w.Promise);try{await p;assert(false);}catch(e){assert(e===sentinel);}}));
    }
    await check('video default scale is one',()=>withPC(pc=>{assert(sender(pc,'video').getParameters().encodings[0].scaleResolutionDownBy===1);}));
    await check('video accepts zero maxFramerate',()=>withPC(async pc=>{const s=sender(pc,'video'),p=s.getParameters();p.encodings[0].maxFramerate=0;await s.setParameters(p);assert(s.getParameters().encodings[0].maxFramerate===0);}));
    for(const [field,value] of [['scaleResolutionDownBy',.5],['scaleResolutionDownBy',0],['maxFramerate',-1]])await check('video range '+field+' '+value,()=>withPC(async pc=>{const s=sender(pc,'video'),p=s.getParameters();p.encodings[0][field]=value;await rejects(()=>s.setParameters(p),w.RangeError);}));
    await check('audio ignores video-only encoding constraints',()=>withPC(async pc=>{const s=sender(pc),p=s.getParameters();p.encodings[0].maxFramerate=-1;p.encodings[0].scaleResolutionDownBy=.5;await s.setParameters(p);const e=s.getParameters().encodings[0];assert(!('maxFramerate' in e)&&!('scaleResolutionDownBy' in e));}));
    await check('video encodings retain RID order',()=>withPC(async pc=>{const s=sender(pc,'video',{sendEncodings:[{rid:'a'},{rid:'b'}]}),p=s.getParameters();equal(p.encodings.map(e=>e.rid),['a','b']);p.encodings.reverse();await rejects(()=>s.setParameters(p),w.DOMException,'InvalidModificationError');}));
    await check('one connection shares RTCP CNAME',()=>withPC(pc=>{assert(sender(pc).getParameters().rtcp.cname===sender(pc,'video').getParameters().rtcp.cname);}));
    await check('setParameters required dictionaries and empty options conversion',()=>withPC(async pc=>{const s=sender(pc);for(const value of [undefined,null,{},[],{codecs:[]},{codecs:[],headerExtensions:[],rtcp:{},encodings:[]}])await rejects(()=>s.setParameters(value),w.TypeError);await rejects(()=>s.setParameters(),w.TypeError);await rejects(()=>s.setParameters(s.getParameters(),1),w.TypeError);}));
    await check('setParameters dictionary conversion order',()=>withPC(async pc=>{const s=sender(pc),base=s.getParameters(),reads=[],p={};for(const key of ['codecs','headerExtensions','rtcp','encodings','transactionId'])Object.defineProperty(p,key,{get(){reads.push(key);return base[key];}});await s.setParameters(p);equal(reads,['codecs','headerExtensions','rtcp','encodings','transactionId']);}));
    for(const kind of ['audio','video'])await check(kind+' same-kind replaceTrack and stable old tracks',()=>withPC(async pc=>{const source=pc.addTransceiver(kind).receiver.track,s=sender(pc,kind);let settled=false;const promise=s.replaceTrack(source);promise.then(()=>settled=true);assert(s.track===null&&!settled);await promise;assert(s.track===source&&source.readyState==='live');const newer=source.clone();await s.replaceTrack(newer);assert(s.track===newer&&source.readyState==='live'&&newer.readyState==='live');await s.replaceTrack(null);assert(s.track===null&&newer.readyState==='live');}));
    await check('replaceTrack explicit undefined is nullable, missing rejected',()=>withPC(async pc=>{const s=sender(pc);await s.replaceTrack(undefined);assert(s.track===null);await rejects(()=>s.replaceTrack(),w.TypeError);}));
    await check('replaceTrack wrong kind precedes closed state',async()=>{const pc=new P(),audio=pc.addTransceiver('audio'),video=pc.addTransceiver('video');pc.close();await rejects(()=>audio.sender.replaceTrack(video.receiver.track),w.TypeError);await rejects(()=>audio.sender.replaceTrack(audio.receiver.track),w.DOMException,'InvalidStateError');});
    await check('replaceTrack stopped sender rejects',()=>withPC(async pc=>{const t=pc.addTransceiver('audio');t.stop();await rejects(()=>t.sender.replaceTrack(null),w.DOMException,'InvalidStateError');}));
    await check('replaceTrack accepts ended native tracks',()=>withPC(async pc=>{const t=pc.addTransceiver('audio'),s=sender(pc),track=t.receiver.track;track.stop();await s.replaceTrack(track);assert(s.track===track&&track.readyState==='ended');}));
    await check('replaceTrack sequential operations complete in order',()=>withPC(async pc=>{const s=sender(pc),a=pc.addTransceiver('audio').receiver.track,b=a.clone(),events=[];const first=s.replaceTrack(a).then(()=>{assert(s.track===a);events.push('first');});const second=s.replaceTrack(b).then(()=>{assert(s.track===b);events.push('second');});const offer=pc.createOffer().then(()=>events.push('offer'));await Promise.all([first,second,offer]);equal(events,['first','second','offer']);}));
    await check('replaceTrack preserves SDP track identity',()=>withPC(async pc=>{const original=pc.addTransceiver('audio').receiver.track,t=pc.addTransceiver(original),s=t.sender;const before=(await pc.createOffer()).sdp;await s.replaceTrack(original.clone());const after=(await pc.createOffer()).sdp;equal(before.split('\r\n').filter(l=>l.startsWith('a=msid:')),after.split('\r\n').filter(l=>l.startsWith('a=msid:')));}));
    await check('setStreams deduplicates native IDs and updates SDP',()=>withPC(async pc=>{const track=pc.addTransceiver('audio').receiver.track,s=pc.addTransceiver(track).sender,a=new w.MediaStream(),b=new w.MediaStream(),aId=a.id,bId=b.id;s.setStreams(a,a,b);const offer=await pc.createOffer(),lines=offer.sdp.split('\r\n').filter(l=>l.startsWith('a=msid:')&&(l.includes(aId)||l.includes(bId)));assert(lines.length===2&&lines[0]==='a=msid:'+aId+' '+track.id&&lines[1]==='a=msid:'+bId+' '+track.id);s.setStreams();const cleared=(await pc.createOffer()).sdp;assert(!cleared.includes(aId)&&!cleared.includes(bId)&&cleared.includes('a=msid:- '+track.id));}));
    await check('setStreams uses native ID rather than author getter',()=>withPC(async pc=>{const track=pc.addTransceiver('audio').receiver.track,s=pc.addTransceiver(track).sender,stream=new w.MediaStream(),id=stream.id;Object.defineProperty(stream,'id',{get(){throw Error('author id getter');}});s.setStreams(stream);assert((await pc.createOffer()).sdp.includes('a=msid:'+id+' '));}));
    await check('setStreams variadic brands before closed state',async()=>{const pc=new P(),s=sender(pc),stream=new w.MediaStream();pc.close();raises(()=>s.setStreams(stream),w.DOMException,'InvalidStateError');for(const bad of [[],[stream],{},Object.create(stream),new Proxy(stream,{})])raises(()=>s.setStreams(bad),w.TypeError);});
    await check('sender receiver brands and callee-realm promise rejections',()=>withPC(async pc=>{const s=sender(pc);for(const fake of [{},Object.create(S.prototype),Object.create(s),new Proxy(s,{})]){raises(()=>S.prototype.getParameters.call(fake),w.TypeError);raises(()=>S.prototype.setStreams.call(fake),w.TypeError);for(const name of ['setParameters','replaceTrack']){const p=S.prototype[name].call(fake);assert(p instanceof w.Promise);await rejects(()=>p,w.TypeError);}}}));
    await check('author proxy traps are not used for receiver or track brands',()=>withPC(async pc=>{const t=pc.addTransceiver('audio'),s=t.sender;let traps=0;const handler={get(){traps++;throw Error('proxy trap');},getPrototypeOf(){traps++;throw Error('prototype trap');}};await rejects(()=>S.prototype.replaceTrack.call(new Proxy(s,handler),null),w.TypeError);await rejects(()=>s.replaceTrack(new Proxy(t.receiver.track,handler)),w.TypeError);raises(()=>s.setStreams(new Proxy(new w.MediaStream(),handler)),w.TypeError);assert(traps===0);}));
    await check('revoked native-looking proxies are rejected',()=>withPC(async pc=>{const t=pc.addTransceiver('audio'),s=t.sender,r=Proxy.revocable(t.receiver.track,{});r.revoke();await rejects(()=>s.replaceTrack(r.proxy),w.TypeError);const q=Proxy.revocable(s,{});q.revoke();await rejects(()=>S.prototype.setParameters.call(q.proxy,{}),w.TypeError);}));
    await check('createOffer conversion errors reject in callee realm',()=>withPC(async pc=>{let reads=0;await rejects(()=>P.prototype.createOffer.call({}, {get iceRestart(){reads++;return false;}}),w.TypeError);assert(reads===0);const sentinel={};try{await pc.createOffer({get offerToReceiveAudio(){throw sentinel;}});assert(false);}catch(e){assert(e===sentinel);}await rejects(()=>pc.createOffer(1),w.TypeError);}));
    await check('local description dictionary copied before networking task',()=>withPC(async pc=>{sender(pc);const offer=await pc.createOffer(),input={...offer};const done=pc.setLocalDescription(input);input.type='rollback';input.sdp='forged';assert(pc.localDescription===null);await done;assert(pc.localDescription instanceof w.RTCSessionDescription&&pc.localDescription.type==='offer'&&pc.localDescription.sdp===offer.sdp&&pc.localDescription!==input);}));
    await check('cross-realm genuine sender uses the callee realm',()=>withPC(async pc=>{const s=sender(pc),other=index===0?document.querySelector('iframe').contentWindow:window,api=other.RTCRtpSender.prototype,p=api.getParameters.call(s);assert(p instanceof other.Object&&p.encodings instanceof other.Array);const done=api.setParameters.call(s,p);assert(done instanceof other.Promise);await done;const track=pc.addTransceiver('audio').receiver.track,replaced=api.replaceTrack.call(s,track);assert(replaced instanceof other.Promise);await replaced;assert(s.track===track);api.setStreams.call(s,new other.MediaStream());}));
    await check('implicit local offer and rollback',()=>withPC(async pc=>{sender(pc);await pc.setLocalDescription();assert(pc.signalingState==='have-local-offer'&&pc.localDescription.type==='offer');await pc.setLocalDescription({type:'rollback'});assert(pc.signalingState==='stable'&&pc.localDescription===null&&pc.pendingLocalDescription===null);}));
  }
  globalThis.__uiEventResults={complete:true,total:checks.length,passed:checks.filter(row=>row.passed).length,checks};
  return checks.every(row=>row.passed);
})()
